=========== overlay-color-contrast.mjs
// The presentation overlay script — the one whose output the owner looks at.
// The 3-panel debug view in measure_vessels.py is deliberately NOT in scope: it
// dims the original and uses red for arteries, which is fine for a QA render and
// wrong for the presentation figure.
const PRESENTATION = 'analysis/annotate_overlays.py';

// An (r, g, b) or (r, g, b, a) literal — the only way a drawn colour is spelled
// in this script (PIL fill=/np.array colours).
const TUPLE = /\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*\d{1,3}\s*)?\)/g;

// Red-dominant = bright red channel that clearly beats BOTH others. Magenta
// (255, 0, 255) and the yellow label colour (255, 235, 60) stay legal: they read
// against the red signal because blue resp. green carries them.
const MARGIN = 60;
const isRedDominant = (r, g, b) => r >= 128 && r - g >= MARGIN && r - b >= MARGIN;

const rule = {
  id: 'overlay-color-contrast',
  severity: 'blocking',
  description: 'Presentation overlay marks must not be red-dominant',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'the gP-CD31 signal being measured IS red — a red outline, arrow or ring vanishes on the very vessels it is supposed to mark',

  run(ctx) {
    const text = ctx.read(PRESENTATION);
    if (text === null) return [];
    const out = [];
    text.split('\n').forEach((line, i) => {
      // A comment or a docstring line describes a colour, it doesn't draw one.
      if (line.trim().startsWith('#')) return;
      for (const m of line.matchAll(TUPLE)) {
        const [r, g, b] = [m[1], m[2], m[3]].map(Number);
        if (!isRedDominant(r, g, b)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file: PRESENTATION,
          line: i + 1,
          what: `overlay colour (${r}, ${g}, ${b}) is red-dominant`,
          why: rule.why,
          fix: 'pick a colour that contrasts with the red channel — cyan for capillaries, green for arteries, magenta for junctions, yellow for labels (see the pack RULES.md)',
          doc: rule.doc,
        });
      }
    });
    return out;
  },
};

export default rule;
=========== rendered-overlays-untracked.mjs
// Rendered output lives under analysis/ (measure_vessels.py --overlays writes
// analysis/overlays/, annotate_overlays.py writes analysis/annotated/); both are
// gitignored and regenerated. The real source images live under references/.
const RENDER_ROOT = 'analysis/';
const IMAGE = /\.(png|jpe?g|tiff?|gif|bmp|webp)$/i;

const rule = {
  id: 'rendered-overlays-untracked',
  severity: 'blocking',
  description: 'No rendered overlay image is committed under analysis/',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an overlay PNG is a regenerable render, not data — committing one freezes a snapshot that silently stops matching the scripts, and the owner\'s rule is that only real data or an agreed ground-truth image gets committed',

  run(ctx) {
    return ctx.tracked
      .filter((f) => f.startsWith(RENDER_ROOT) && IMAGE.test(f))
      .map((f) => ({
        rule: rule.id,
        severity: rule.severity,
        file: f,
        line: null,
        what: `${f} is a tracked image under ${RENDER_ROOT}`,
        why: rule.why,
        fix: 'untrack it (git rm --cached) and regenerate with python3 analysis/measure_vessels.py --overlays or python3 analysis/annotate_overlays.py — commit the script and the numeric results instead; if the image really is data or agreed ground truth, put it under references/',
        doc: rule.doc,
      }));
  },
};

export default rule;
=========== panel-scale-calibration.mjs
// Every panel in the working dataset is named VESSEL_<fig>_<region>_...; the
// px -> um scale is measured per FIGURE from that figure's printed 50 um bar and
// tabulated as SCALEBAR_PX in the extraction script.
const PANEL = /^references\/figures\/panels\/VESSEL_(fig\d+)_/;
const MEASURE = 'analysis/measure_vessels.py';
const TABLE = /SCALEBAR_PX\s*=\s*\{([^}]*)\}/;

const rule = {
  id: 'panel-scale-calibration',
  severity: 'blocking',
  description: 'Every working panel figure has a scale-bar calibration',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an uncalibrated figure does not fail — it silently reports "um n/a" and drops out of every length and density number, so a panel added without its bar measurement quietly shrinks the result set',

  run(ctx) {
    const text = ctx.read(MEASURE);
    if (text === null) return [];
    const lines = text.split('\n');
    const lineOf = (needle) => lines.findIndex((l) => l.includes(needle)) + 1 || null;
    const m = TABLE.exec(text);
    if (!m) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: null,
        what: 'no SCALEBAR_PX table found',
        why: rule.why,
        fix: 'keep the per-figure scale-bar widths in a SCALEBAR_PX = { ... } table in this file — it is the single calibration source annotate_overlays.py imports',
        doc: rule.doc,
      }];
    }
    const calibrated = new Set([...m[1].matchAll(/['"]([^'"]+)['"]\s*:/g)].map((k) => k[1]));
    const figures = new Set();
    for (const f of ctx.tracked) {
      const hit = PANEL.exec(f);
      if (hit) figures.add(hit[1]);
    }
    return [...figures].sort()
      .filter((fig) => !calibrated.has(fig))
      .map((fig) => ({
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: lineOf('SCALEBAR_PX'),
        what: `${fig} has VESSEL_ panels but no SCALEBAR_PX entry`,
        why: rule.why,
        fix: `measure the 50 um bar on ${fig}'s merge/montage panel (same resolution as its VESSEL panel) and add '${fig}': <bar width in px> to SCALEBAR_PX`,
        doc: rule.doc,
      }));
  },
};

export default rule;

=========== scale-numbers-match-calibration.mjs
// The px -> um scale of every figure is derived from ONE source: UM_PER_BAR /
// SCALEBAR_PX in the extraction script (the measured 50 um bar widths). The docs
// quote those numbers in three places (the pack RULES, the working guide, the
// results calibration table) — this check keeps the copies honest.
//
// Detection is column/label-scoped, never a bare grep for decimals: a claim is
// read only from an inline `figN = <value>` in a passage that says "um/px", or
// from a markdown table's own um/px and bar-width COLUMNS, and only when the
// figure cell names a figure rather than a panel. That is what keeps the per-panel
// results table (fig1_C1_healthy | 2145 | 23.6 | ...) out of scope.
const MEASURE = 'analysis/measure_vessels.py';
const SKIP = '.claudinite/shared/';                 // read-only mounted canon
const UM_PER_BAR = /UM_PER_BAR\s*=\s*([\d.]+)/;
const TABLE = /SCALEBAR_PX\s*=\s*\{([^}]*)\}/;

const MU = '[µμu]';                       // micro sign / greek mu / plain "u"
const MU_LABEL = 'µm/px';
const UMPP = new RegExp(`${MU}m\\s*/\\s*px`, 'i');  // the unit that marks a scale claim
// "fig1 = 0.820", "fig4/5/6 = 0.658", "fig4 / fig5 = 0.658"
const INLINE = /\bfig(\d+(?:\s*\/\s*(?:fig)?\d+)*)\s*=\s*\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)/g;
// a table cell that is just a number, optionally in px and/or bold: "61 px", "**0.820**"
const NUM_CELL = /^\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)\s*(?:px)?\s*\*{0,2}$/;

// The figures a label names — "fig1", "fig4/5/6", "fig4 / fig5". Anything that is
// not a bare figure number is dropped, so a panel-level label ("fig1_C1_healthy",
// "fig1 crop A2") names no figure and carries no claim.
const figsOf = (labels) => labels
  .split(/[/,]/)
  .map((p) => p.trim().replace(/^fig/i, ''))
  .filter((p) => /^\d+$/.test(p))
  .map((p) => `fig${p}`);

// A quoted value agrees if it matches the true value rounded to the precision the
// doc chose to quote it at (0.820, 0.82 and 0.8197 all describe 50/61).
const agrees = (quoted, truth) => {
  const dp = (quoted.split('.')[1] || '').length;
  return Number(quoted) === Number(truth.toFixed(dp));
};

const cells = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());

// Blank-line-separated blocks, with the 1-based line each block starts on.
const blocks = (text) => {
  const out = [];
  let cur = null;
  text.split('\n').forEach((line, i) => {
    if (line.trim() === '') { cur = null; return; }
    if (!cur) { cur = { start: i + 1, lines: [] }; out.push(cur); }
    cur.lines.push(line);
  });
  return out;
};

const rule = {
  id: 'scale-numbers-match-calibration',
  severity: 'blocking',
  description: 'Scale numbers quoted in the docs match the SCALEBAR_PX calibration',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'the um/px per figure is derived from one measured table (UM_PER_BAR / SCALEBAR_PX); a doc that quotes a stale copy does not fail loudly — it silently re-labels every length and density number in that document with the wrong scale',

  run(ctx) {
    const src = ctx.read(MEASURE);
    if (src === null) return [];
    const perBar = UM_PER_BAR.exec(src);
    const table = TABLE.exec(src);
    // No calibration source to compare against: panel-scale-calibration owns that.
    if (!perBar || !table) return [];
    const bar = new Map(
      [...table[1].matchAll(/['"]([^'"]+)['"]\s*:\s*(\d+(?:\.\d+)?)/g)].map((m) => [m[1], Number(m[2])]),
    );
    const um = Number(perBar[1]);
    const truth = (fig, kind) => {
      const px = bar.get(fig);
      if (px === undefined) return null;               // uncalibrated figure -> not this rule
      return kind === 'bar' ? px : um / px;
    };

    const out = [];
    const flag = (file, line, fig, kind, quoted, expected) => out.push({
      rule: rule.id,
      severity: rule.severity,
      file,
      line,
      what: kind === 'bar'
        ? `${fig}'s scale bar is quoted as ${quoted} px but SCALEBAR_PX says ${expected}`
        : `${fig}'s scale is quoted as ${quoted} ${MU_LABEL} but SCALEBAR_PX gives ${expected}`,
      why: rule.why,
      fix: kind === 'bar'
        ? `quote ${fig}'s bar as ${expected} px, or fix SCALEBAR_PX in ${MEASURE} if the measurement changed — the table is the single source`
        : `quote ${expected} ${MU_LABEL} for ${fig} (UM_PER_BAR / SCALEBAR_PX['${fig}']), or fix the table in ${MEASURE} if the measurement changed`,
      doc: rule.doc,
    });

    for (const file of ctx.tracked) {
      if (!file.endsWith('.md') || file.startsWith(SKIP)) continue;
      const text = ctx.read(file);
      if (text === null) continue;

      for (const blk of blocks(text)) {
        const body = blk.lines.join('\n');
        if (!UMPP.test(body)) continue;               // no scale claim in this passage

        // --- inline prose claims: "fig1 = 0.820" ---------------------------
        blk.lines.forEach((line, i) => {
          if (line.trim().startsWith('|')) return;    // table rows handled below
          for (const m of line.matchAll(INLINE)) {
            for (const fig of figsOf(m[1])) {
              const t = truth(fig, 'umpp');
              if (t === null) continue;
              if (!agrees(m[2], t)) flag(file, blk.start + i, fig, 'umpp', m[2], t.toFixed(3));
            }
          }
        });

        // --- table columns: a um/px column and/or a bar-width column -------
        const rows = blk.lines.map((l, i) => ({ line: blk.start + i, raw: l }))
          .filter((r) => r.raw.trim().startsWith('|'));
        if (rows.length < 3) continue;
        const head = cells(rows[0].raw);
        const figCol = head.findIndex((c) => /fig/i.test(c));
        const umppCol = head.findIndex((c) => UMPP.test(c));
        const barCol = head.findIndex((c, i) => i !== umppCol && /bar/i.test(c) && /px|m\b/i.test(c));
        if (figCol < 0 || (umppCol < 0 && barCol < 0)) continue;
        for (const row of rows.slice(2)) {            // skip header + |---| separator
          const cs = cells(row.raw);
          const label = (cs[figCol] || '').replace(/\*/g, '').trim();
          for (const [col, kind] of [[umppCol, 'umpp'], [barCol, 'bar']]) {
            if (col < 0) continue;
            const hit = NUM_CELL.exec(cs[col] || '');
            if (!hit) continue;
            for (const fig of figsOf(label)) {
              const t = truth(fig, kind);
              if (t === null) continue;
              if (!agrees(hit[1], t)) {
                flag(file, row.line, fig, kind, hit[1], kind === 'bar' ? String(t) : t.toFixed(3));
              }
            }
          }
        }
      }
    }
    return out;
  },
};

export default rule;
=========== locked-metric-fields.mjs
// The extraction script is the single place the three locked metrics are
// computed and named; every downstream table, overlay banner and results
// markdown quotes those field names back.
const MEASURE = 'analysis/measure_vessels.py';

// The professor's three asks, and the metric fields each one is locked to.
const LOCKED = [
  { ask: 'COUNT', meaning: 'branch segments (junction-to-junction / junction-to-tip)', fields: ['segments'] },
  { ask: 'CATEGORIZE', meaning: 'caliber - capillary vs penetrating artery by centerline diameter', fields: ['capillary', 'artery'] },
  { ask: 'MEASURE', meaning: 'total centerline length, as raw um and as density', fields: ['length_um', 'length_density'] },
];

// Parse rather than grep: the metric names count only where they are built as
// keyword fields of a dict(...) construction, never where prose, a docstring or
// a print format string happens to mention them. `defaultdict(` is not a dict
// construction here, hence the non-word/non-dot lookbehind.
const DICT = /(?<![\w.])dict\s*\(/g;
const KWARG = /(?:^|[(,]\s*)([A-Za-z_]\w*)\s*=(?!=)/g;

// The real metrics dict carries trailing `#` comments between its fields, which
// would otherwise sit between a field and the comma that anchors the next one.
// Blank them (keeping the newline) rather than the whole line, so line numbers
// still count. Quote-aware: a `#` inside a string literal is not a comment.
function stripComments(text) {
  return text.split('\n').map((line) => {
    let quote = null;
    for (let i = 0; i < line.length; i += 1) {
      const c = line[i];
      if (quote) {
        if (c === '\\') i += 1;
        else if (c === quote) quote = null;
      } else if (c === '"' || c === "'") quote = c;
      else if (c === '#') return line.slice(0, i);
    }
    return line;
  }).join('\n');
}

// The fields of every dict(...) built in the script, with the line the first
// dict carrying a locked field starts on (where a reviewer should look).
function reportedFields(source) {
  const text = stripComments(source);
  const fields = new Set();
  let dicts = 0;
  let line = null;
  for (const m of text.matchAll(DICT)) {
    dicts += 1;
    let depth = 0;
    let end = m.index + m[0].length - 1;
    for (; end < text.length; end += 1) {
      if (text[end] === '(') depth += 1;
      else if (text[end] === ')' && (depth -= 1) === 0) break;
    }
    const body = text.slice(m.index, end + 1);
    const here = [...body.matchAll(KWARG)].map((k) => k[1]);
    if (line === null && here.some((f) => LOCKED.some((l) => l.fields.includes(f)))) {
      line = text.slice(0, m.index).split('\n').length;
    }
    here.forEach((f) => fields.add(f));
  }
  return { fields, dicts, line };
}

const rule = {
  id: 'locked-metric-fields',
  severity: 'blocking',
  description: 'The extraction script still reports all three locked metrics',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'COUNT / CATEGORIZE / MEASURE are locked definitions - dropping or renaming one of their fields changes what every recorded number means, and it fails silently: the metric just stops appearing in the tables it used to anchor',

  run(ctx) {
    const text = ctx.read(MEASURE);
    if (text === null) return [];
    const { fields, dicts, line } = reportedFields(text);
    if (dicts === 0) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: null,
        what: 'no metrics dict found in the extraction script',
        why: rule.why,
        fix: 'keep the per-panel metrics built as a dict(field=...) in this file - it is the one place the locked metric names are defined',
        doc: rule.doc,
      }];
    }
    return LOCKED
      .map((lock) => ({ lock, missing: lock.fields.filter((f) => !fields.has(f)) }))
      .filter(({ missing }) => missing.length)
      .map(({ lock, missing }) => ({
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line,
        what: `${lock.ask} is locked to ${lock.meaning}, but the metrics dict reports no ${missing.join(' / ')} field`,
        why: rule.why,
        fix: `report ${missing.join(' and ')} again from the metrics dict; if the definition of ${lock.ask} really is changing, that is an owner decision - unlock it in the pack RULES.md first, then re-record every number that was measured under the old definition`,
        doc: rule.doc,
      }));
  },
};

export default rule;

// Red-first fixtures for this pack's checks: each rule is shown FIRING on a
// violating input and QUIET on a clean one. Dependency-free — run it with
//   node .claudinite/local/packs/vascular-coloring/pack.test.mjs
import assert from 'node:assert/strict';

import overlayColorContrast from './overlay-color-contrast.mjs';
import renderedOverlaysUntracked from './rendered-overlays-untracked.mjs';
import panelScaleCalibration from './panel-scale-calibration.mjs';
import scaleNumbersMatchCalibration from './scale-numbers-match-calibration.mjs';
import lockedMetricFields from './locked-metric-fields.mjs';

// The slice of the check context these rules use: file reads and the tracked list.
const ctx = ({ files = {}, tracked = [] }) => ({
  tracked,
  read: (p) => (p in files ? files[p] : null),
});

const cases = [];
const test = (name, fn) => cases.push([name, fn]);

// --- overlay-color-contrast -------------------------------------------------

const OVERLAY = 'analysis/annotate_overlays.py';

test('overlay-color-contrast fires on a red overlay colour', () => {
  const findings = overlayColorContrast.run(ctx({
    files: { [OVERLAY]: 'CAP_COL, ART_COL = (0, 200, 255), (255, 60, 30)\n' },
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 1);
  assert.match(findings[0].what, /red-dominant/);
});

test('overlay-color-contrast is quiet on the agreed palette', () => {
  const findings = overlayColorContrast.run(ctx({
    files: {
      [OVERLAY]: [
        '# an example artery gets a red arrow  <- prose, not a drawn colour',
        'CAP_COL, ART_COL, JUN_COL = (0, 200, 255), (40, 235, 90), (255, 0, 255)',
        'label = (255, 235, 60)',
        'white = (255, 255, 255)',
      ].join('\n'),
    },
  }));
  assert.deepEqual(findings, []);
});

// --- rendered-overlays-untracked --------------------------------------------

test('rendered-overlays-untracked fires on a committed overlay PNG', () => {
  const findings = renderedOverlaysUntracked.run(ctx({
    tracked: ['analysis/annotated/VESSEL_fig3_ischemic_gP-CD31_red.png', 'analysis/measure_vessels.py'],
  }));
  assert.equal(findings.length, 1);
  assert.match(findings[0].file, /^analysis\/annotated\//);
});

test('rendered-overlays-untracked is quiet on scripts plus source images', () => {
  const findings = renderedOverlaysUntracked.run(ctx({
    tracked: [
      'analysis/measure_vessels.py',
      'analysis/results-first-pass.md',
      'references/figures/panels/VESSEL_fig3_ischemic_gP-CD31_red.png',
    ],
  }));
  assert.deepEqual(findings, []);
});

// --- panel-scale-calibration -------------------------------------------------

const MEASURE = 'analysis/measure_vessels.py';
const withTable = (keys) =>
  `UM_PER_BAR = 50.0\nSCALEBAR_PX = {${keys.map((k) => `'${k}': 61`).join(', ')}}\n`;

test('panel-scale-calibration fires on a panel figure with no bar measurement', () => {
  const findings = panelScaleCalibration.run(ctx({
    files: { [MEASURE]: withTable(['fig1']) },
    tracked: [
      'references/figures/panels/VESSEL_fig1_C1_healthy_gP-CD31_red.png',
      'references/figures/panels/VESSEL_fig9_ischemic_gP-CD31_red.png',
    ],
  }));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /fig9/);
  assert.equal(findings[0].line, 2);
});

test('panel-scale-calibration is quiet when every panel figure is calibrated', () => {
  const findings = panelScaleCalibration.run(ctx({
    files: { [MEASURE]: withTable(['fig1', 'fig3']) },
    tracked: [
      'references/figures/panels/VESSEL_fig1_C1_healthy_gP-CD31_red.png',
      'references/figures/panels/VESSEL_fig3_ischemic_gP-CD31_red.png',
      // fig7 has panels but no VESSEL_ panel — not in the working dataset.
      'references/figures/panels/fig7_capillaries_gP-CD31.png',
    ],
  }));
  assert.deepEqual(findings, []);
});

// --- locked-metric-fields ----------------------------------------------------

// A metrics dict shaped like the real one, minus whichever fields a case drops.
// Interleaved comments included deliberately: the real dict carries them, and a
// comment between two fields must not hide the field that follows it.
const metricsScript = (fields) => [
  '"""Delivers the professor\'s three asks per image:',
  '  - COUNT : number of branch segments (junction-to-junction pieces)',
  '"""',
  'ARTERY_DIAM_PX = 9.0',
  '',
  'def analyze(rgb, umpp):',
  '    m = dict(area=100 * mask.mean(),',
  '             # scale-invariant, comparable across figures:',
  `             ${fields.map((f) => `${f}=v_${f}`).join(', ')},`,
  '             wp90=round(float(np.percentile(widths, 90)), 1))',
  '    return m, dict(mask=mask, skel=skel)',
].join('\n');

const ALL_LOCKED = ['segments', 'capillary', 'artery', 'length_um', 'length_density'];

test('locked-metric-fields fires when the count unit stops being reported', () => {
  // COUNT re-pointed at connected components: `segments` is gone as a field and
  // survives only in the docstring — a text grep would be satisfied, the check
  // is not, because it reads the metrics dict.
  const findings = lockedMetricFields.run(ctx({
    files: {
      [MEASURE]: metricsScript(['vessels', 'capillary', 'artery', 'length_um', 'length_density']),
    },
  }));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /COUNT is locked to branch segments/);
  assert.match(findings[0].what, /no segments field/);
  assert.equal(findings[0].line, 7);
});

test('locked-metric-fields reports each locked ask that lost a field', () => {
  const findings = lockedMetricFields.run(ctx({
    files: { [MEASURE]: metricsScript(['segments', 'capillary', 'length_um']) },
  }));
  assert.deepEqual(findings.map((f) => f.what.split(' is locked')[0]), ['CATEGORIZE', 'MEASURE']);
  assert.match(findings[0].what, /no artery field/);
  assert.match(findings[1].what, /no length_density field/);
});

test('locked-metric-fields is quiet when all three asks are still reported', () => {
  const findings = lockedMetricFields.run(ctx({ files: { [MEASURE]: metricsScript(ALL_LOCKED) } }));
  assert.deepEqual(findings, []);
});

test('locked-metric-fields fires when the metrics dict itself is gone', () => {
  const findings = lockedMetricFields.run(ctx({
    files: { [MEASURE]: 'def analyze(rgb, umpp):\n    return defaultdict(list)\n' },
  }));
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /no metrics dict found/);
});

// --- scale-numbers-match-calibration ----------------------------------------

